		}
		return doCreateUndefinedUnit(address);
	}

	protected T next<T>(Iterator<T> it) {
		if (it.hasNext()) {
			return it.next();
		}
		return null;
	}

	protected Comparator<CodeUnit> getUnitComparator(bool forward) {
		return forward ? (u1, u2) => u1.getMinAddress().compareTo(u2.getMinAddress())
				: (u1, u2) => -u1.getMinAddress().compareTo(u2.getMinAddress());
	}

	protected Iterator<T> getTopCodeIterator<T>/* where T : TraceCodeUnit */(
